#!/usr/bin/env node

/**
 * Generates supabase/seed.sql from data/products.json and data/settings.json.
 *
 * Usage:
 *   node scripts/generate-seed-sql.mjs
 *
 * This is the no-network fallback for environments where the Supabase REST
 * endpoint cannot be reached. Paste the generated file into the Supabase SQL
 * Editor. `corepack pnpm seed:supabase` is the normal path once the project URL
 * resolves.
 */

import { readFile, writeFile } from "node:fs/promises"
import path from "node:path"
import { fileURLToPath } from "node:url"
import { findDuplicateProduct, validateProductRecord } from "../lib/product-rules.mjs"
import { productToRow } from "../lib/product-row.mjs"

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..")
const PRODUCTS_FILE = path.join(ROOT, "data", "products.json")
const SETTINGS_FILE = path.join(ROOT, "data", "settings.json")
const OUTPUT_FILE = path.join(ROOT, "supabase", "seed.sql")

const products = JSON.parse(await readFile(PRODUCTS_FILE, "utf8"))
const settings = JSON.parse(await readFile(SETTINGS_FILE, "utf8"))

if (!Array.isArray(products)) throw new Error("data/products.json must be a JSON array.")

// Same gate the runtime store enforces, so the SQL file cannot introduce data
// the admin API would reject.
const errors = []
for (const [index, product] of products.entries()) {
  const { errors: recordErrors } = validateProductRecord(product, {
    allProducts: products,
    selfIndex: index,
  })
  for (const message of recordErrors) {
    errors.push(`${product?.id ?? "(missing id)"}: ${message}`)
  }

  const duplicateIndex = findDuplicateProduct(products, product?.brand, product?.name, index)
  if (duplicateIndex !== -1) {
    errors.push(`${product?.id}: duplicate brand + name with ${products[duplicateIndex]?.id}`)
  }
}
if (errors.length > 0) {
  throw new Error(`Refusing to generate seed.sql:\n- ${errors.join("\n- ")}`)
}

const productRows = products.map((product, index) => productToRow(product, index))
const partnerRows = (Array.isArray(settings.partners) ? settings.partners : [])
  .filter((partner) => partner && typeof partner.name === "string" && typeof partner.url === "string")
  .map((partner, index) => ({
    name: partner.name,
    url: partner.url,
    new_tab: partner.newTab === true,
    position: index,
  }))

const productsJson = JSON.stringify(productRows)
const socialLinksJson = JSON.stringify(settings.socialLinks ?? {})
const contentJson = JSON.stringify(settings.content ?? {})
const partnersJson = JSON.stringify(partnerRows)

// Pick a dollar-quote tag that does not appear in the payloads.
function dollarQuote(payload) {
  let tag = "frostdew"
  let suffix = 0
  while (payload.includes(`$${tag}$`)) {
    suffix += 1
    tag = `frostdew${suffix}`
  }
  return `$${tag}$${payload}$${tag}$`
}

for (const [label, payload] of Object.entries({
  products: productsJson,
  socialLinks: socialLinksJson,
  content: contentJson,
  partners: partnersJson,
})) {
  if (payload.includes("\u0000")) throw new Error(`${label} contains a NUL byte.`)
}
if (/\r/.test(productsJson + socialLinksJson + contentJson + partnersJson)) {
  throw new Error("Seed payload contains a carriage return.")
}

const sql = `-- FrostDew seed for Supabase.
--
-- Generated by scripts/generate-seed-sql.mjs from data/products.json and
-- data/settings.json. Do not edit by hand; regenerate after editing the JSON.
--
-- Requires supabase/schema.sql (or supabase/migrations/20261027_integration.sql)
-- to have been applied first.
--
-- Safe to re-run: products are upserted by id and the settings + partner list
-- are replaced atomically through save_site_settings().

begin;

-- ---------------------------------------------------------------------------
-- Products (${productRows.length}) — upsert keeps existing rows and adds missing
-- ones. sort_order stores the curated catalog order.
-- ---------------------------------------------------------------------------

with seed as (
  select *
  from jsonb_to_recordset(${dollarQuote(productsJson)}::jsonb) as x(
    id text,
    brand text,
    name text,
    full_name text,
    categories text[],
    short text,
    description text,
    features text[],
    image text,
    images text[],
    url text,
    store text,
    bestseller boolean,
    sort_order integer,
    price text,
    sale_price text,
    rating numeric,
    review_count integer,
    added_date date,
    affiliate_links jsonb,
    related_products text[]
  )
)
insert into public.products (
  id, brand, name, full_name, categories, short, description, features,
  image, images, url, store, bestseller, sort_order, price, sale_price,
  rating, review_count, added_date, affiliate_links, related_products
)
select
  id, brand, name, full_name, categories, short, description, features,
  image, images, url, store, bestseller, sort_order, price, sale_price,
  rating, review_count, added_date,
  coalesce(affiliate_links, '{}'::jsonb),
  coalesce(related_products, '{}'::text[])
from seed
on conflict (id) do update set
  brand            = excluded.brand,
  name             = excluded.name,
  full_name        = excluded.full_name,
  categories       = excluded.categories,
  short            = excluded.short,
  description      = excluded.description,
  features         = excluded.features,
  image            = excluded.image,
  images           = excluded.images,
  url              = excluded.url,
  store            = excluded.store,
  bestseller       = excluded.bestseller,
  sort_order       = excluded.sort_order,
  price            = excluded.price,
  sale_price       = excluded.sale_price,
  rating           = excluded.rating,
  review_count     = excluded.review_count,
  added_date       = excluded.added_date,
  affiliate_links  = excluded.affiliate_links,
  related_products = excluded.related_products;

-- ---------------------------------------------------------------------------
-- Site settings + ${partnerRows.length} partner link(s), written as one unit.
-- ---------------------------------------------------------------------------

select public.save_site_settings(
  ${dollarQuote(socialLinksJson)}::jsonb,
  ${dollarQuote(contentJson)}::jsonb,
  ${dollarQuote(partnersJson)}::jsonb
);

commit;

-- Verification -----------------------------------------------------------------
select count(*) as products, count(distinct brand_key || ' / ' || name_key) as unique_brand_names
from public.products;

select count(*) as partners from public.partners;

select id, updated_at from public.site_settings where id = 'default';
`

await writeFile(OUTPUT_FILE, sql, "utf8")

console.log(`Wrote ${path.relative(ROOT, OUTPUT_FILE)}`)
console.log(`- products: ${productRows.length}`)
console.log(`- partners: ${partnerRows.length}`)
console.log(`- size: ${(Buffer.byteLength(sql) / 1024).toFixed(0)} KB`)
